exercises.solution:
public class Main {
    interface Writer { int write(String b); }
    static class Logger implements Writer {
        public int write(String b) { return b.length(); }
    }

    public static void main(String[] args) {
        Logger logger = new Logger();
        int n = logger.write("hello");
        System.out.println(n + " hello");
    }
}

